/**
 * Parses e-commerce order JSON payloads posted to an Apex REST endpoint.
 */
public with sharing class OrderPayloadParser {

    public class PayloadException extends Exception {}

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public static OrderPayloadParser.Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Request body is null or blank.');
        }

        Object root;
        try {
            root = JSON.deserializeUntyped(body);
        } catch (System.JSONException je) {
            throw new PayloadException('Request body is not valid JSON: ' + je.getMessage());
        }

        if (!(root instanceof Map<String, Object>)) {
            throw new PayloadException('Request body must be a JSON object.');
        }
        Map<String, Object> rootMap = (Map<String, Object>) root;

        OrderPayloadParser.Order ord = new OrderPayloadParser.Order();

        // number
        Object numberVal = rootMap.get('number');
        if (numberVal == null || !(numberVal instanceof String) || String.isBlank((String) numberVal)) {
            throw new PayloadException('Missing or blank required property (number).');
        }
        ord.orderNumber = (String) numberVal;

        // date (optional, ISO yyyy-MM-dd)
        Object dateVal = rootMap.get('date');
        if (dateVal != null) {
            if (!(dateVal instanceof String)) {
                throw new PayloadException('Property (date) must be a string in yyyy-MM-dd format.');
            }
            try {
                ord.orderDate = Date.valueOf((String) dateVal);
            } catch (System.StringException se) {
                throw new PayloadException('Property (date) is not a valid yyyy-MM-dd date: ' + dateVal);
            }
        }

        // currency (optional)
        Object currencyVal = rootMap.get('currency');
        if (currencyVal instanceof String) {
            ord.currencyCode = (String) currencyVal;
        }

        // customer (optional; customerEmail may be null)
        Object customerVal = rootMap.get('customer');
        if (customerVal instanceof Map<String, Object>) {
            Map<String, Object> customerMap = (Map<String, Object>) customerVal;
            Object emailVal = customerMap.get('email');
            if (emailVal instanceof String) {
                ord.customerEmail = (String) emailVal;
            }
        }

        // lines
        ord.lines = new List<Line>();
        Object linesVal = rootMap.get('lines');
        if (linesVal != null) {
            if (!(linesVal instanceof List<Object>)) {
                throw new PayloadException('Property (lines) must be a JSON array.');
            }
            List<Object> rawLines = (List<Object>) linesVal;
            for (Object rawLine : rawLines) {
                if (!(rawLine instanceof Map<String, Object>)) {
                    throw new PayloadException('Each entry in (lines) must be a JSON object.');
                }
                ord.lines.add(parseLine((Map<String, Object>) rawLine));
            }
        }

        // totals
        ord.total = 0;
        for (Line ln : ord.lines) {
            ord.total += ln.lineTotal;
        }
        ord.total = ord.total.setScale(2, System.RoundingMode.HALF_UP);

        return ord;
    }

    private static Line parseLine(Map<String, Object> lineMap) {
        Line ln = new Line();

        // sku
        Object skuVal = lineMap.get('sku');
        if (skuVal == null || !(skuVal instanceof String) || String.isBlank((String) skuVal)) {
            throw new PayloadException('Line is missing a required (sku).');
        }
        ln.sku = (String) skuVal;

        // quantity
        Object qtyVal = lineMap.get('quantity');
        if (qtyVal == null || !(qtyVal instanceof Integer) || (Integer) qtyVal <= 0) {
            throw new PayloadException('Line ' + ln.sku + ' has a missing or non-positive (quantity).');
        }
        ln.quantity = (Integer) qtyVal;

        // unitPrice
        Object priceVal = lineMap.get('unitPrice');
        if (priceVal == null || !(priceVal instanceof Decimal) || (Decimal) priceVal < 0) {
            throw new PayloadException('Line ' + ln.sku + ' has a missing or negative (unitPrice).');
        }
        ln.unitPrice = (Decimal) priceVal;

        // discount: missing or null means 0
        Object discountVal = lineMap.get('discount');
        if (discountVal instanceof Decimal) {
            ln.discount = (Decimal) discountVal;
        } else {
            ln.discount = 0;
        }

        // lineTotal: quantity x unitPrice x (1 - discount), half-up at 2 dp
        Decimal gross = ln.unitPrice * ln.quantity;
        ln.lineTotal = gross.multiply(1 - ln.discount).setScale(2, System.RoundingMode.HALF_UP);

        return ln;
    }

    public static String toAcknowledgement(OrderPayloadParser.Order order) {
        Map<String, Object> ack = new Map<String, Object>();
        ack.put('number', order.orderNumber);
        ack.put('status', 'RECEIVED');
        ack.put('lineCount', order.lines == null ? 0 : order.lines.size());
        ack.put('total', order.total);
        return JSON.serialize(ack);
    }
}
