@isTest
private class ShippingCostCalculatorTest {

    private static void assertQuote(Decimal expected, Decimal weightKg, String zone, Boolean express, Decimal orderValue) {
        Decimal actual = ShippingCostCalculator.quote(weightKg, zone, express, orderValue);
        System.assertEquals(expected, actual,
            'quote(' + weightKg + ', ' + zone + ', ' + express + ', ' + orderValue + ')');
    }

    private static void assertThrows(Decimal weightKg, String zone, Boolean express, Decimal orderValue) {
        Boolean threw = false;
        try {
            ShippingCostCalculator.quote(weightKg, zone, express, orderValue);
        } catch (ShippingCostCalculator.ShippingException e) {
            threw = true;
        }
        System.assert(threw, 'Expected ShippingException for weight=' + weightKg +
            ', zone=' + zone + ', express=' + express + ', orderValue=' + orderValue);
    }

    // ---------- weight validation ----------

    @isTest
    static void testWeightValidation() {
        assertThrows(0, 'DOMESTIC', false, null);
        assertThrows(-0.01, 'DOMESTIC', false, null);
        assertThrows(-5, 'EU', true, 50);
        assertThrows(null, 'DOMESTIC', false, null);
    }

    // ---------- weight tiers (boundaries) ----------

    @isTest
    static void testWeightTierBoundaries() {
        // up to and including 1 kg: 5.00
        assertQuote(5.00, 0.01, 'DOMESTIC', false, null);
        assertQuote(5.00, 1, 'DOMESTIC', false, null);
        // above 1 up to 5 kg: 9.50
        assertQuote(9.50, 1.01, 'DOMESTIC', false, null);
        assertQuote(9.50, 5, 'DOMESTIC', false, null);
        // above 5 up to 20 kg: 18.00
        assertQuote(18.00, 5.01, 'DOMESTIC', false, null);
        assertQuote(18.00, 20, 'DOMESTIC', false, null);
        // above 20: 18.00 + 0.75 per started kilogram above 20
        assertQuote(18.75, 20.01, 'DOMESTIC', false, null); // 1 started kg above 20
        assertQuote(18.75, 21, 'DOMESTIC', false, null);    // exactly 1 kg above 20
        assertQuote(19.50, 22, 'DOMESTIC', false, null);    // 2 kg above 20
        assertQuote(21.75, 24.99, 'DOMESTIC', false, null); // 4.99 -> 5 started kg above 20
        assertQuote(21.75, 25, 'DOMESTIC', false, null);    // 5 kg above 20
    }

    // ---------- zones ----------

    @isTest
    static void testZoneFactors() {
        assertQuote(9.50, 2, 'DOMESTIC', false, null);  // x1.0
        assertQuote(13.30, 2, 'EU', false, null);       // 9.50 * 1.4
        assertQuote(20.90, 2, 'WORLD', false, null);    // 9.50 * 2.2
    }

    @isTest
    static void testZoneCaseInsensitive() {
        assertQuote(9.50, 2, 'domestic', false, null);
        assertQuote(13.30, 2, 'eu', false, null);
        assertQuote(20.90, 2, 'world', false, null);
        assertQuote(9.50, 2, 'Domestic', false, null);
    }

    @isTest
    static void testInvalidZones() {
        assertThrows(2, null, false, null);
        assertThrows(2, 'MARS', false, null);
        assertThrows(2, '', false, null);
    }

    // ---------- express ----------

    @isTest
    static void testExpressAdds50Percent() {
        assertQuote(14.25, 2, 'DOMESTIC', true, null);  // 9.50 * 1.5
        assertQuote(31.35, 3, 'WORLD', true, null);     // 9.50 * 2.2 * 1.5
    }

    @isTest
    static void testNullExpressIsStandard() {
        assertQuote(9.50, 2, 'DOMESTIC', null, null);
        assertQuote(20.90, 2, 'WORLD', null, null);
    }

    @isTest
    static void testExpressOverridesFreeShipping() {
        // Express DOMESTIC with orderValue >= 100 is NOT free
        assertQuote(14.25, 2, 'DOMESTIC', true, 250.00);
        // And free-shipping check must not swallow express pricing elsewhere
        assertQuote(31.35, 3, 'WORLD', true, 250.00);
    }

    // ---------- free domestic standard shipping ----------

    @isTest
    static void testFreeDomesticStandardShipping() {
        assertQuote(0, 2, 'DOMESTIC', false, 100.00);
        assertQuote(0, 30, 'DOMESTIC', false, 250.00);
        assertQuote(0, 0.5, 'DOMESTIC', null, 100.00); // null express = standard
    }

    @isTest
    static void testFreeShippingNotApplied() {
        // just below threshold
        assertQuote(9.50, 2, 'DOMESTIC', false, 99.99);
        // order value null
        assertQuote(9.50, 2, 'DOMESTIC', false, null);
        // non-domestic zone with high order value
        assertQuote(13.30, 2, 'EU', false, 500.00);
        assertQuote(20.90, 2, 'WORLD', false, 500.00);
    }

    // ---------- rounding ----------

    @isTest
    static void testRoundingHalfUp() {
        // 21 kg DOMESTIC express: 18.75 * 1.5 = 28.125 -> 28.13 (half up)
        assertQuote(28.13, 21, 'DOMESTIC', true, null);
        // 1 kg WORLD express: 5.00 * 2.2 = 11.00 * 1.5 = 16.50
        assertQuote(16.50, 1, 'WORLD', true, null);
        // 4 kg EU express: 9.50 * 1.4 = 13.30 * 1.5 = 19.95
        assertQuote(19.95, 4, 'EU', true, null);
        // 22 kg WORLD express: 19.50 * 2.2 = 42.90 * 1.5 = 64.35
        assertQuote(64.35, 22, 'WORLD', true, null);
        // 2 kg EU: 9.50 * 1.4 = 13.30
        assertQuote(13.30, 2, 'EU', false, null);
    }
