/**
 * Utility to retrieve the active picklist values of any picklist or
 * multi-select picklist field, chosen at runtime.
 */
public inherited sharing class PicklistService {

    public class PicklistServiceException extends Exception {}

    public class Option {
        public String value { get; set; }
        public String label { get; set; }
        public Boolean isDefault { get; set; }
    }

    /**
     * Returns the active values of the given picklist / multi-select picklist
     * field, in the order defined on the field.
     *
     * @param objectApiName Object API name (standard or custom), case-insensitive.
     * @param fieldApiName  Field API name (standard or custom), case-insensitive.
     * @return Active options in field-definition order.
     * @throws PicklistServiceException on null/blank names, unknown object,
     *         unknown field, or non-picklist field.
     */
    public static List<PicklistService.Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName)) {
            throw new PicklistServiceException('Object API name must not be null or blank.');
        }
        if (String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Field API name must not be null or blank.');
        }

        // Resolve the object, case-insensitively (the map keys are lowercase,
        // and map lookups are case-insensitive, so 'account' / 'ACCOUNT' work).
        Schema.SObjectType sobjType = Schema.getGlobalDescribe().get(objectApiName.trim());
        if (sobjType == null) {
            throw new PicklistServiceException(
                'Object \'' + objectApiName + '\' does not exist.');
        }

        // Resolve the field, case-insensitively.
        Map<String, Schema.SObjectField> fields = sobjType.getDescribe().fields.getMap();
        Schema.SObjectField field = fields.get(fieldApiName.trim());
        if (field == null) {
            throw new PicklistServiceException(
                'Field \'' + fieldApiName + '\' does not exist on object \'' + objectApiName + '\'.');
        }

        Schema.DescribeFieldResult dfr = field.getDescribe();

        Schema.DisplayType fieldType = dfr.getType();
        if (fieldType != Schema.DisplayType.PICKLIST && fieldType != Schema.DisplayType.MULTIPICKLIST) {
            throw new PicklistServiceException(
                'Field \'' + fieldApiName + '\' on object \'' + objectApiName +
                '\' is not a picklist or multi-select picklist.');
        }

        List<PicklistService.Option> options = new List<PicklistService.Option>();
        // getPicklistValues() returns entries in field-definition order and,
        // by default, excludes inactive values.
        for (Schema.PicklistEntry entry : dfr.getPicklistValues()) {
            if (!entry.isActive()) {
                continue;
            }
            PicklistService.Option opt = new PicklistService.Option();
            opt.value = entry.getValue();
            opt.label = entry.getLabel();
            opt.isDefault = entry.isDefaultValue();
            options.add(opt);
        }
        return options;
    }
}
