public with sharing class OpportunityRollupService {

    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> result = new Map<Id, Decimal>();
        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        // Initialize every requested account to 0 so no key is ever missing or null.
        for (Id accountId : accountIds) {
            result.put(accountId, 0);
        }

        Date today = Date.today();
        Date startDate = Date.newInstance(today.year(), 1, 1);
        Date endDate = Date.newInstance(today.year(), 12, 31);

        List<AggregateResult> aggregates = [
            SELECT AccountId accId, SUM(Amount) totalAmount
            FROM Opportunity
            WHERE AccountId IN :accountIds
              AND IsWon = true
              AND CloseDate >= :startDate
              AND CloseDate <= :endDate
            GROUP BY AccountId
        ];

        for (AggregateResult ar : aggregates) {
            Id accId = (Id) ar.get('accId');
            Object totalObj = ar.get('totalAmount');
            Decimal total = totalObj == null ? 0 : (Decimal) totalObj;
            result.put(accId, total);
        }

        return result;
    }
}
