public inherited sharing class Opportunities extends fflib_SObjectDomain {

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> records) {
            return new Opportunities(records);
        }
    }

    public Opportunities(List<Opportunity> records) {
        super(records);
    }

    public override void onAfterInsert() {
        startFulfilmentFor(getNewlyWonIds(null));
    }

    public override void onAfterUpdate(Map<Id, SObject> existingRecords, Map<Id, SObject> priorRecords) {
        startFulfilmentFor(getNewlyWonIds(priorRecords));
    }

    private static void startFulfilmentFor(Set<Id> opportunityIds) {
        if (opportunityIds.isEmpty()) {
            return;
        }
        IOpportunityFulfilmentService service =
            (IOpportunityFulfilmentService) Application.Service.newInstance(IOpportunityFulfilmentService.class);
        service.startFulfilment(opportunityIds);
    }

    private Set<Id> getNewlyWonIds(Map<Id, SObject> priorRecords) {
        Set<Id> qualifyingIds = new Set<Id>();
        for (SObject obj : getRecords()) {
            Opportunity opp = (Opportunity) obj;
            if (opp.StageName != 'Closed Won') {
                continue;
            }
            if (priorRecords == null) {
                // Insert: any Closed Won opportunity qualifies.
                qualifyingIds.add(opp.Id);
                continue;
            }
            Opportunity prior = (Opportunity) priorRecords.get(opp.Id);
            if (prior != null && prior.StageName != 'Closed Won') {
                qualifyingIds.add(opp.Id);
            }
        }
        return qualifyingIds;
    }
}
