public with sharing class FollowUpTaskService {

    /**
     * Creates a follow-up Task for each opportunity in the weekly pipeline review.
     *
     * Tasks are inserted with allOrNone=false in bulk: a Task rejected by a
     * validation rule does not stop the others from being created. The Ids of
     * the opportunities whose Task could not be created are returned.
     *
     * @param opportunityIds Ids of the opportunities to create follow-ups for.
     * @return Set of opportunity Ids for which the follow-up Task was NOT created.
     */
    public static Set<Id> createFollowUps(List<Id> opportunityIds) {
        Set<Id> failedIds = new Set<Id>();

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return failedIds;
        }

        // Preserve order and avoid duplicates when the same Id is passed twice.
        List<Id> distinctIds = new List<Id>(new Set<Id>(opportunityIds));

        Map<Id, Opportunity> opps = new Map<Id, Opportunity>(
            [SELECT Id, Name, OwnerId FROM Opportunity WHERE Id IN :distinctIds]
        );

        List<Task> tasks = new List<Task>();
        Map<Integer, Id> taskIndexToOppId = new Map<Integer, Id>();
        for (Opportunity opp : opps.values()) {
            tasks.add(new Task(
                WhatId = opp.Id,
                OwnerId = opp.OwnerId,
                Subject = 'Follow up: ' + opp.Name,
                ActivityDate = Date.today().addDays(7),
                Status = 'Not Started',
                Priority = 'Normal'
            ));
            taskIndexToOppId.put(tasks.size() - 1, opp.Id);
        }

        if (!tasks.isEmpty()) {
            // Insert in chunks of 200 in case the caller ever exceeds the
            // per-DML-statement record limit; each chunk is one DML statement.
            for (List<Task> chunk : splitIntoChunks(tasks, 200)) {
                List<Database.SaveResult> results = Database.insert(chunk, false);
                for (Integer i = 0; i < results.size(); i++) {
                    if (!results[i].isSuccess()) {
                        failedIds.add(taskIndexToOppId.get(i));
                    }
                }
            }
        }

        // Any requested Id that no longer exists (or wasn't accessible) also failed.
        for (Id oppId : distinctIds) {
            if (!opps.containsKey(oppId)) {
                failedIds.add(oppId);
            }
        }

        return failedIds;
    }

    private static List<List<Task>> splitIntoChunks(List<Task> records, Integer size) {
        List<List<Task>> chunks = new List<List<Task>>();
        for (Integer i = 0; i < records.size(); i += size) {
            Integer end = Math.min(i + size, records.size());
            chunks.add(records.subList(i, end));
        }
        return chunks;
    }
}
```

Wait — the chunking introduces a bug: `taskIndexToOppId.get(i)` uses the chunk-local index but the map holds global indices. Corrected version below uses per-chunk offset tracking.

