trigger OpportunityTrigger on Opportunity (after insert, after update) {
    for (Opportunity opp : Trigger.new) {
        Opportunity old = Trigger.isInsert ? null : Trigger.oldMap.get(opp.Id);

        Boolean stageChanged = Trigger.isInsert ||
            (old.StageName != opp.StageName);
        Boolean amountChanged = Trigger.isInsert ||
            (old.Amount != opp.Amount);

        Boolean wasOpen = Trigger.isUpdate && isOpen(old);
        Boolean isOpenNow = isStageOpen(opp.StageName);

        // Recalculate when an open opportunity's stage/amount changes,
        // or when a previously open opportunity is closed (rating may drop).
