```javascript
import { LightningElement, api } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const REFRESH_INTERVAL_MS = 60000;

export default class QueueMonitor extends LightningElement {
    @api title = 'Support Queue Monitor';

    waiting;
    longestWaitMinutes;
    error;
    loaded = false;

    _intervalId = null;
    _inFlight = false;
    _visibilityHandler = null;

    connectedCallback() {
        this._visibilityHandler = () => {
            if (document.visibilityState === 'visible') {
                this.stopPolling();
                this.startPolling();
            }
        };
        document.addEventListener('visibilitychange', this._visibilityHandler);
        this.startPolling();
    }

    disconnectedCallback() {
        this.stopPolling();
        if (this._visibilityHandler) {
            document.removeEventListener('visibilitychange', this._visibilityHandler);
            this._visibilityHandler = null;
        }
    }

    startPolling() {
        this.loadStats();
        this._intervalId = setInterval(() => {
            if (document.visibilityState === 'hidden') {
                return; // skip refresh while tab is hidden
            }
            this.loadStats();
        }, REFRESH_INTERVAL_MS);
    }

    stopPolling() {
        if (this._intervalId !== null) {
            clearInterval(this._intervalId);
            this._intervalId = null;
        }
    }

    loadStats() {
        if (this._inFlight) {
            return; // skip; previous request still in flight
        }
        this._inFlight = true;
        getQueueStats()
            .then((result) => {
                if (result) {
                    this.waiting = result.waiting;
                    this.longestWaitMinutes = result.longestWaitMinutes;
                    this.error = undefined;
                    this.loaded = true;
                }
            })
            .catch((error) => {
                this.error = this.reduceError(error);
            })
            .finally(() => {
                this._inFlight = false;
            });
    }

    reduceError(error) {
        if (error && error.body && error.body.message) {
            return error.body.message;
        }
        return 'An unexpected error occurred.';
    }
}
