public with sharing class RecurringGiftService {

    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31
        public Date startDate;
        public Integer installments;  // null or 0 = no end date
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    private static final String PERIOD_MONTHLY = 'Monthly';
    private static final String RECURRING_TYPE_OPEN = 'Open';
    private static final String RECURRING_TYPE_FIXED = 'Fixed';
    private static final String STATUS_ACTIVE = 'Active';
    private static final String OPEN_ENDED_OPEN = 'Open';

    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        List<Id> result = new List<Id>();

        // Null or empty list -> empty list.
        if (requests == null || requests.isEmpty()) {
            return result;
        }

        // Validate everything BEFORE any DML so a bad request aborts the whole call safely.
        for (GiftRequest req : requests) {
            if (req == null) {
                throw new RecurringGiftException('Request cannot be null.');
            }
            if (req.contactId == null) {
                throw new RecurringGiftException('Contact is required for every gift request.');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new RecurringGiftException(
                    'Amount must be a positive number (contact: ' + req.contactId + ').'
                );
            }
            if (req.dayOfMonth == null || req.dayOfMonth < 1 || req.dayOfMonth > 31) {
                throw new RecurringGiftException(
                    'dayOfMonth must be between 1 and 31 (contact: ' + req.contactId + ').'
                );
            }
            if (req.startDate == null) {
                throw new RecurringGiftException(
                    'startDate is required (contact: ' + req.contactId + ').'
                );
            }
            if (req.installments != null && req.installments < 0) {
                throw new RecurringGiftException(
                    'installments must be null, 0 (open-ended) or a positive number (contact: '
                    + req.contactId + ').'
                );
            }
        }

        List<npe03__Recurring_Donation__c> toInsert = new List<npe03__Recurring_Donation__c>();

        for (GiftRequest req : requests) {
            Boolean openEnded = (req.installments == null || req.installments == 0);
            Boolean lastDayOfMonth = (req.dayOfMonth == 31);

            npe03__Recurring_Donation__c rd = new npe03__Recurring_Donation__c(
                npe03__Contact__c = req.contactId,
                npe03__Amount__c = req.amount,
                npe03__Installment_Period__c = PERIOD_MONTHLY,
                npe03__Date_Established__c = req.startDate,
                npe03__Next_Payment_Date__c = req.startDate,
                // Enhanced Recurring Donations fields
                npsp__StartDate__c = req.startDate,
                npsp__InstallmentFrequency__c = String.valueOf(1), // every 1 month
                npsp__Day_of_Month__c = (lastDayOfMonth ? null : req.dayOfMonth),
                npsp__Always_Use_Last_Day_Of_Month__c = lastDayOfMonth,
                npsp__Status__c = STATUS_ACTIVE,
                npsp__PaymentMethod__c = req.paymentMethod
            );

            if (openEnded) {
                rd.npsp__RecurringType__c = RECURRING_TYPE_OPEN;
                rd.npe03__Open_Ended_Status__c = OPEN_ENDED_OPEN;
            } else {
                rd.npsp__RecurringType__c = RECURRING_TYPE_FIXED;
                rd.npe03__Installments__c = req.installments;
            }

            toInsert.add(rd);
        }

        try {
            insert toInsert;
        } catch (DmlException e) {
            throw new RecurringGiftException(
                'Failed to create recurring donations: ' + e.getDmlMessage(0), e
            );
        }

        // All-or-nothing insert: ids come back in request order because insert preserves list order.
        for (npe03__Recurring_Donation__c rd : toInsert) {
            result.add(rd.Id);
        }
        return result;
    }
}
```

