```apex
/**
 * TDTM trigger handler that creates a follow-up task for major gifts.
 *
 * Register in NPSP Trigger Configuration:
 *   Class: OPP_MajorGiftFollowUp_TDTM
 *   Object: Opportunity
 *   Trigger Action: AfterInsert;AfterUpdate
 *   Load Order: 5
 *   Asynchronous: unchecked
 *
 * Creates a single "Major gift thank-you call" Task when an Opportunity
 * becomes Closed Won with Amount >= 5000 (and was not already qualified),
 * and never duplicates on subsequent edits.
 *
 * The handler performs its own single DML statement (the task insert) and
 * uses no SOQL queries, so it is bulk-safe for 200 opportunities.
 */
public class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    private static final String TASK_SUBJECT  = 'Major gift thank-you call';
    private static final String TASK_PRIORITY = 'High';
    private static final String TASK_STATUS   = 'Not Started';
    private static final Decimal MIN_AMOUNT   = 5000;
    private static final String STAGE_CLOSED_WON = 'Closed Won';

    public override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        if (newlist == null || newlist.isEmpty()) {
            return null;
        }

        if (triggerAction != npsp.TDTM_Runnable.Action.AfterInsert
                && triggerAction != npsp.TDTM_Runnable.Action.AfterUpdate) {
            return null;
        }

        Map<Id, Opportunity> oldOpps = new Map<Id, Opportunity>();
        if (oldlist != null) {
            for (SObject so : oldlist) {
                Opportunity o = (Opportunity) so;
                oldOpps.put(o.Id, o);
            }
        }

        List<Task> tasksToInsert = new List<Task>();

        for (SObject so : newlist) {
            Opportunity newOpp = (Opportunity) so;
            Opportunity oldOpp = oldOpps.get(newOpp.Id);

            // If the gift already qualified before this update, do not
            // create another task.
            if (oldOpp != null && qualifies(oldOpp)) {
                continue;
            }

            if (qualifies(newOpp)) {
                tasksToInsert.add(buildTask(newOpp));
            }
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert; // single DML statement
        }

        return null; // nothing further for the TDTM dispatcher to execute
    }

    private static Task buildTask(Opportunity opp) {
        return new Task(
            Subject      = TASK_SUBJECT,
            Priority     = TASK_PRIORITY,
            Status       = TASK_STATUS,
            WhatId       = opp.Id,
            WhoId        = opp.npsp__Primary_Contact__c,
            OwnerId      = opp.OwnerId,
            ActivityDate = opp.CloseDate != null
                               ? opp.CloseDate.addDays(3)
                               : null
        );
    }

    /**
     * A gift qualifies when it is Closed Won with Amount >= 5000.
     * StageName is checked because IsWon/IsClosed may not be populated on
     * in-memory SObject instances (they are derived fields), and IsWon is
     * checked as a fallback for records where only the flags are set.
     */
    private static Boolean qualifies(Opportunity o) {
        if (o == null) {
            return false;
        }
        Boolean isWon = (o.IsWon == true) || STAGE_CLOSED_WON.equals(o.StageName);
        return isWon
            && o.Amount != null
            && o.Amount >= MIN_AMOUNT;
    }
}
```

**What was wrong and fixed:** the original version relied solely on the derived `IsWon`/`IsClosed` fields. Those flags are not populated on in-memory `Opportunity` instances (and in some contexts only `StageName` reflects the closed-won state), so `qualifies()` returned false and no tasks were ever created. The corrected `qualifies()` now checks `StageName == 'Closed Won'` as well as `IsWon`, so it works both for records passed in memory by the dispatcher/tests and for records loaded from the database. Everything else (no SOQL, one DML, skip-if-already-qualified, task field mapping, CloseDate + 3 days) remains as specified.

