```apex
public with sharing class RecordAccessService {

    private static final Integer MAX_IDS_PER_QUERY = 200; // UserRecordAccess IN filter limit

    /**
     * Returns the subset of recordIds the running user can edit,
     * per UserRecordAccess.HasEditAccess.
     * Bulk-safe: batches queries to respect SOQL and IN-clause limits.
     */
    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> result = new Set<Id>();
        if (recordIds == null || recordIds.isEmpty()) {
            return result;
        }

        List<Id> idList = new List<Id>(recordIds);
        Integer totalBatches = Math.ceil((Decimal)idList.size() / MAX_IDS_PER_QUERY).intValue();

        for (Integer i = 0; i < totalBatches; i++) {
            Integer startIdx = i * MAX_IDS_PER_QUERY;
            Integer stopIdx = Math.min(startIdx + MAX_IDS_PER_QUERY, idList.size());

            List<Id> batch = new List<Id>();
            for (Integer j = startIdx; j < stopIdx; j++) {
                batch.add(idList[j]);
            }

            for (UserRecordAccess ura : [
                SELECT RecordId
                FROM UserRecordAccess
                WHERE UserId = :UserInfo.getUserId()
                  AND HasEditAccess = true
                  AND RecordId IN :batch
            ]) {
                result.add(ura.RecordId);
            }
        }

        return result;
    }
}
```

